char * CDECL getenv(const char *name)
{
    char *ret;

    if (!MSVCRT_CHECK_PMT(name != NULL)) return NULL;

    _lock(_ENV_LOCK);
    ret = getenv_helper(name);
    _unlock(_ENV_LOCK);
    return ret;
}

